import os
import tarfile

def file_exists(file_path):
    """Verifica si el archivo existe."""
    return os.path.isfile(file_path)

def extract_tar_file(tar_path, extract_to):
    """Extrae un archivo tar comprimido en el directorio especificado."""
    if not file_exists(tar_path):
        print(f"Error: El archivo {tar_path} no existe.")
        return

    try:
        with tarfile.open(tar_path, "r:gz") as tar:
            tar.extractall(path=extract_to)
        print(f"Archivos extraídos exitosamente en {extract_to}")
    except tarfile.TarError as e:
        print(f"Error al extraer el archivo tar: {e}")
    except PermissionError as e:
        print(f"Permiso denegado al extraer archivos: {e}")
    except Exception as e:
        print(f"Ocurrió un error inesperado: {e}")

# Uso de la función
if __name__ == "__main__":
    tar_file = "/tmp/data.tar.gz"
    extract_directory = "/tmp/unpack"

    # Asegurarse de que el directorio de extracción exista
    os.makedirs(extract_directory, exist_ok=True)

    extract_tar_file(tar_file, extract_directory)

